"""Pipeline context — shared mutable state and frozen value objects.

Defines the dataclasses that flow through the pipeline:

* :class:`Scenario` — a frozen test case generated by a probe.
* :class:`StageResult` — a frozen outcome from a single pipeline stage.
* :class:`StageError` — a frozen error record captured during execution.
* :class:`EvalContext` — the *mutable* state object threaded through every
  stage in the pipeline.

Design notes
------------
``EvalContext`` is deliberately mutable (``@dataclass`` without ``frozen``).
Stages mutate specific fields — ``pre_check_result``, ``scenarios``,
``responses``, ``scores``, ``errors`` — as they execute.  The ``skill``
and ``rubric`` fields are treated as read-only inputs by convention
(REQ-S05).

Type annotations use ``Any`` with inline comments for forward-referenced
types to avoid circular imports at runtime.  The ``TYPE_CHECKING`` block
provides full type information for static analysers.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from typing import Any, TYPE_CHECKING

if TYPE_CHECKING:
    from md_evals.pipeline.config import PipelineConfig
    from md_evals.pipeline.skill_parser import ParsedSkill
    from md_evals.precheck import PreCheckResult
    from md_evals.rubric import RubricConfig
    from md_evals.scoring import DimensionScore


# ─── Frozen Value Objects ───


@dataclass(frozen=True)
class Scenario:
    """A test scenario generated by a probe.

    Frozen value object representing a single test case.  Created by
    :class:`~md_evals.pipeline.protocols.Probe` implementations and
    consumed by the target stage (which sends the ``prompt`` to an LLM)
    and the judge stage (which evaluates the response).

    Attributes:
        id: Globally unique identifier (UUID4 string by default).
        probe_name: Name of the probe that generated this scenario.
        prompt: The test prompt to send to the target LLM.
        expected_behavior: Description of what a good response looks like.
        dimension: Target rubric dimension, or empty string for general.
        metadata: Arbitrary key-value pairs for lineage tracking and
            phase-3 evidence tracing.
    """

    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    probe_name: str = ""
    prompt: str = ""
    expected_behavior: str = ""
    dimension: str = ""
    metadata: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class StageResult:
    """Result from a pipeline stage execution.

    Frozen value object returned by every
    :meth:`~md_evals.pipeline.protocols.PipelineStage.execute` call.
    The ``success`` flag indicates whether the stage completed its
    primary task; even on failure the pipeline may continue.

    Attributes:
        success: ``True`` if the stage completed without critical errors.
        duration_ms: Wall-clock execution time in milliseconds.
        error: Human-readable error message if ``success`` is ``False``.
        data: Stage-specific output data for debugging or extension.
    """

    success: bool = True
    duration_ms: int = 0
    error: str | None = None
    data: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class StageError:
    """Error recorded during pipeline execution.

    Frozen value object appended to ``EvalContext.errors`` when a stage
    fails, times out, or raises an unexpected exception.

    Attributes:
        stage_name: Identifier of the stage that produced the error.
        error_type: Category string — ``"stage_failure"``, ``"timeout"``,
            ``"llm_error"``, ``"parse_error"``, or the exception class name.
        message: Human-readable description of what went wrong.
        timestamp: ISO 8601 timestamp of when the error was recorded
            (may be empty if timing is not available).
    """

    stage_name: str = ""
    error_type: str = ""
    message: str = ""
    timestamp: str = ""


# ─── Mutable Pipeline Context ───


@dataclass
class EvalContext:
    """Mutable context passed through pipeline stages.

    This is the central data structure of the pipeline.  It is created
    before the first stage and threaded through every subsequent stage.
    Each stage reads the fields it needs and writes its outputs:

    * **PreCheckStage** writes ``pre_check_result``.
    * **AuditorStage** writes ``scenarios``.
    * **TargetStage** writes ``responses``.
    * **JudgeStage** writes ``scores``.

    The ``skill`` and ``rubric`` fields are read-only by convention —
    stages MUST NOT replace or mutate them.

    Attributes:
        skill: Parsed SKILL.md representation (set before pipeline starts).
        rubric: Rubric configuration for grading (set before pipeline starts).
        pipeline_config: Pipeline configuration (set before pipeline starts).
        skill_path: Filesystem path to the evaluated SKILL.md file.
        pre_check_result: Result from the pre-check stage, or ``None``
            if the pre-check has not yet run.
        scenarios: Test scenarios generated by the auditor stage.
        responses: Mapping of scenario ID → target LLM response text.
        scores: Dimension scores produced by the judge stage.
        metadata: Arbitrary key-value pairs for timing, model info, etc.
        errors: Errors recorded during pipeline execution.
    """

    # ── Read-only inputs (set before pipeline starts) ──
    skill: Any = None  # ParsedSkill
    rubric: Any = None  # RubricConfig
    pipeline_config: Any = None  # PipelineConfig
    skill_path: str = ""

    # ── Mutable outputs (populated by stages) ──
    pre_check_result: Any = None  # PreCheckResult | None
    scenarios: list[Any] = field(default_factory=list)  # list[Scenario]
    responses: dict[str, str] = field(default_factory=dict)  # scenario_id → response
    scores: list[Any] = field(default_factory=list)  # list[DimensionScore]

    # ── Cross-cutting ──
    metadata: dict[str, Any] = field(default_factory=dict)
    errors: list[Any] = field(default_factory=list)  # list[StageError]
